    fun get(lang: String, key: String, vararg args: Any): String {
        val index = when (lang) { "en" -> 1; "es" -> 2; "de" -> 3; "zh" -> 4; else -> 0 }
        var value = values[key]?.getOrNull(index) ?: key
        args.forEachIndexed { i, arg -> value = value.replace("{$i}", arg.toString()) }
        return value
    }
}
